try{previousPersonalAvailable=!!localStorage.getItem(PREVIOUS_PERSONAL_KEY);legacyAvailable=!!localStorage.getItem(LEGACY_KEY);const stored=localStorage.getItem(KEY);if(stored){state=parseImport(stored);status='이 브라우저에 저장한 조건을 불러왔습니다.';}}catch{status='저장된 조건을 읽지 못해 기본값을 사용합니다.';}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const warning=()=>`<div class="warning"><span aria-hidden="true">△</span>${DISCLAIMER}</div>`;
function amount(v){const sign=v<0?'−':'',n=Math.abs(v);if(state.display.format==='decimal')return sign+(n/1e8).toLocaleString('ko-KR',{minimumFractionDigits:2,maximumFractionDigits:2})+'억원';const man=Math.round(n/10000),eok=Math.floor(man/10000),rest=man%10000;return sign+(eok?eok.toLocaleString()+'억'+(rest?' '+rest.toLocaleString()+'만원':'원'):man.toLocaleString()+'만원');}
function short(v){return (v/1e8).toFixed(2)+'억';}
function field(label,path,value,{unit='',hint='',step='any',min=0,max,placeholder='',type='number',scale=1}={}){return `<div class="field"><label for="${path}">${label}${unit?` <span class="tiny">(${unit})</span>`:''}</label><input id="${path}" data-path="${path}" data-scale="${scale}" type="${type}" value="${esc(value===undefined||value===null?'':type==='number'?value/scale:value)}" ${type==='number'?`min="${min}" ${max!==undefined?`max="${max}"`:''} step="${step}"`:''} placeholder="${esc(placeholder)}">${hint?`<div class="hint">${hint}</div>`:''}</div>`;}
function select(label,path,value,options){return `<div class="field"><label for="${path}">${label}</label><select id="${path}" data-path="${path}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function check(label,path,val){return `<label class="check"><input type="checkbox" data-path="${path}" ${val?'checked':''}>${label}</label>`;}

function integratedNotice(r){return renderIntegratedNotice(r,state,{escape:esc,amount});}
function integratedDetails(r){return renderIntegratedDetails(r,{escape:esc,amount,stat,warning})+referenceComparison({escape:esc,amount,warning});}
function policyInputs(){return policyInputHTML(state,{field,select,check,years,escape:esc});}
function reviewExport(){return exportData(state);}
function periodEditor(){return `<div class="notice">${POLICY_NOTICE} ${CASH_TIMING_NOTICE}</div><div class="grid six"><div class="field"><label>계산 대상</label><div class="private">개인 1명 · 독립 과세</div></div>${field('계산 시작연도','startYear',state.startYear,{min:2020,max:2050,step:1})}${field('계산 종료연도','endYear',state.endYear,{min:2020,max:2050,step:1})}${field('기본 연봉 인상률','settings.growth',state.settings.growth,{unit:'%',scale:.01,min:-50,max:100,hint:'개인 기본률 적용 버튼 제공'})}${select('OPI2 최초 지급','settings.opi2Delay',state.settings.opi2Delay,[['0','성과연도 당해'],['1','성과연도 다음 해'],['2','성과연도 2년 후']])}${select('금액 표시','display.format',state.display.format,[['korean','1억 2,345만원'],['decimal','1.23억원']])}</div>`;}
function personEditor(p,i){const prefix=`people.${i}`;return `<div class="person"><div class="person-head"><div class="avatar ">0${i+1}</div><input aria-label="사용자 이름" data-path="${prefix}.name" value="${esc(p.name)}" maxlength="40"><span class="pill">독립 과세</span></div><div class="grid three">${select('DS 소속',prefix+'.division',p.division,['메모리','공통','파운드리·시스템LSI'].map(x=>[x,x]))}${select('2025년 직급',prefix+'.grade',p.grade,[['CL1·CL2','CL1·CL2'],['CL3·CL4','CL3·CL4']])}${field(state.dataStartYear+'년 기준 계약연봉',prefix+'.salary',p.salary,{unit:'만원',scale:10000,step:.0001})}${field('기본 인상률',prefix+'.growth',p.growth,{unit:'%',scale:.01,min:-50,max:100})}${field('직급 연봉 상한',prefix+'.cap',p.cap,{unit:'만원',scale:10000,hint:'0이면 상한 없음'})}${field('연간 고정수당',prefix+'.allowance',p.allowance,{unit:'만원',scale:10000,hint:'과세소득에 항상 포함'})}</div><div class="inline" style="margin-top:12px">${check('고정수당을 OPI1·TAI 산정에 포함 (이전 모형 OPI2에도 적용)',prefix+'.includeAllowance',p.includeAllowance)}<button class="tiny" data-action="growth" data-person="${i}">기본 인상률 적용</button></div><details open><summary>연도별 연봉 · 학술연수</summary><div class="table-wrap"><table class="year-form"><thead><tr><th>연도</th><th>직접 연봉 (만원)</th><th>인상률 (%)</th><th>전체 학술연수</th></tr></thead><tbody>${years(state).map(y=>`<tr><td>${y}<div class="tiny muted" id="salary-${i}-${y}">${amount(salaryAt(p,y,state))}</div></td><td><input aria-label="${esc(p.name)} ${y} 계약연봉 만원" type="number" min="0" step=".0001" data-path="${prefix}.salaries.${y}" data-scale="10000" value="${p.salaries[y]!==undefined?p.salaries[y]/10000:''}" placeholder="자동 산정"></td><td><input class="growth-input" aria-label="${esc(p.name)} ${y} 인상률" type="number" min="-50" max="100" data-path="${prefix}.growthByYear.${y}" data-scale=".01" value="${p.growthByYear[y]!==undefined?p.growthByYear[y]*100:''}" placeholder="기본"></td><td>${check('전체 적용',prefix+`.study.${y}`,p.study[y])}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">빈 연봉은 전년 × 인상률로 산정 후 상한 적용. 직접 입력도 상한을 적용합니다. 학술연수는 연봉 정상, OPI1·TAI 0, OPI2 ${state.settings.studyCoefficient*100}%. 일부 연수도 체크 시 연중 전체 적용.</p></details><details><summary>PSU 주식 · 매도제한 설정</summary><div class="inline">${check('PSU 포함',prefix+'.includePSU',p.includePSU)}</div><div class="grid three" style="margin-top:12px">${select('성과 배수',prefix+'.psuMultiplier',p.psuMultiplier,[0,.5,1,1.3,1.7,2].map(v=>[v,v+'배']))}${field('주당 평가가격',prefix+'.psuPrice',p.psuPrice,{unit:'원',step:1})}${field('PSU 매도제한 기간',prefix+'.psuLock',p.psuLock,{unit:'년',step:1,max:10})}</div><p class="disclosure" id="psu-total-${i}">약정 ${state.settings.psuShares[p.grade]}주 × 배수. ${state.settings.psuYears.join('·')}년 평가가치 1/3씩 지급, 즉시 현금화 가정. 소수 주식은 계산상 평가수량이며 실제 지급 단위는 미확인입니다. 학술연수에도 PSU는 별도 선택을 유지합니다.</p></details></div>`;}
function scenarioEditor(){const k=state.activeScenario,sc=state.scenarios[k];return `<div class="panel-head"><div><h3>연도별 사업성과 가정</h3><p class="subtitle">총 영업이익 가정 · 실제 노사합의의 최종 사업성과 기준과 다를 수 있습니다.</p></div><span class="pill">자동 최신 전망 수집 없음</span></div><div class="scenarios">${Object.entries(state.scenarios).map(([id,v])=>`<button data-action="scenario" data-scenario="${id}" class="${id===k?'active':''}">${esc(v.name)}</button>`).join('')}<button data-action="save-scenario" class="secondary">현재 가정 → 사용자 지정 저장</button></div><div class="inline"><span class="muted tiny">현재 시나리오 입력 프리셋</span><button data-action="performance-preset" data-preset="base">기본 전망</button><button data-action="performance-preset" data-preset="conservative">보수적 전망</button><button data-action="performance-preset" data-preset="optimistic">낙관적 전망 ×1.25</button></div><p class="scenario-note">기본 전망: 사용자 제공 “2026년 9월 5일 당시 외부 전망을 이용한 예시 프리셋”. 낙관적 전망 ×1.25는 근거 있는 최신 전망이 아닌 사용자 조정 예시 배율입니다. 보수적 프리셋은 2026·2027 유지, 2028·2029 미지급, 2030 입력값 유지.</p><div class="table-wrap"><table class="year-form"><thead><tr><th>성과연도</th><th>총 영업이익 가정 (조원)</th><th>입력 프리셋</th><th>지급 기준 (조원)</th><th>미지급</th><th>판정</th><th>최초 지급연도 지정</th></tr></thead><tbody>${years(state).map(y=>`<tr><td>${y}</td><td><input aria-label="${y} 총 영업이익 가정" type="number" min="0" step="any" data-path="scenarios.${k}.performance.${y}" value="${sc.performance[y]??0}"></td><td><select aria-label="${y} 전망 프리셋" data-year-preset="${y}"><option value="direct">직접 입력</option><option value="base">기본 전망</option><option value="conservative">보수적 전망</option><option value="optimistic">낙관적 전망 ×1.25</option></select></td><td><input aria-label="${y} OPI2 지급 기준" type="number" min="0" data-path="settings.thresholds.${y}" value="${state.settings.thresholds[y]??(y<=2028?200:100)}"></td><td>${check('OPI2 미지급',`scenarios.${k}.unpaid.${y}`,sc.unpaid[y])}</td><td id="eligibility-${y}"></td><td><input aria-label="${y} OPI2 최초 지급연도" type="number" min="${y}" max="2065" step="1" data-path="settings.opi2PayYears.${y}" value="${state.settings.opi2PayYears[y]??''}" placeholder="${y+state.settings.opi2Delay}"></td></tr>`).join('')}</tbody></table></div><div class="grid three" style="margin-top:14px">${select('OPI2 전망치 적용',`scenarios.${k}.opi2Factor`,sc.opi2Factor,[[1,'100% 정상'],[.75,'75% 적용'],[.5,'50% 적용'],[0,'전액 미지급']])}${select('PSU 시나리오',`scenarios.${k}.psuMode`,sc.psuMode,[['normal','PSU 정상 달성 (개인 배수)'],['zero','PSU 0배']])}<div class="field"><label>별도 저장</label><p class="tiny muted">3개 시나리오는 서로 독립된 입력 가정입니다. 사용자 조건 저장 시 함께 보관됩니다.</p></div></div>`;}
function advanced(){const c=state.settings,t=c.tax;return `<details id="advanced"><summary>고급 설정 · 산식, 지급률, 세율, 보험료</summary><div class="notice">OPI2 = ${amount(c.opi2Base)} × (성과 ÷ ${c.performanceBase}조원) × (산정연봉 ÷ ${amount(c.salaryBase)}) × 사업부 계수 × 학술연수 계수. 공개 보도액으로 역산한 계산용 기준이며 공식 회사 산식이 아닙니다.</div><div class="advanced-grid">${field('OPI1 지급률','settings.opi1Rate',c.opi1Rate,{unit:'%',scale:.01,max:200})}${field('TAI 연간 지급률','settings.taiRate',c.taiRate,{unit:'%',scale:.01,max:200})}${field('OPI1 지급 지연','settings.opi1Delay',c.opi1Delay,{unit:'년',step:1,max:10})}${field('TAI 지급 지연','settings.taiDelay',c.taiDelay,{unit:'년',step:1,max:10})}${field('OPI2 기준금액','settings.opi2Base',c.opi2Base,{unit:'만원',scale:10000,min:1})}${field('OPI2 기준성과','settings.performanceBase',c.performanceBase,{unit:'조원',min:1})}${field('OPI2 기준연봉','settings.salaryBase',c.salaryBase,{unit:'만원',scale:10000,min:1})}${field('학술연수 계수','settings.studyCoefficient',c.studyCoefficient,{max:2})}${['메모리','공통','파운드리·시스템LSI'].map(d=>field(d+' 계수',`settings.coefficients.${d}`,c.coefficients[d],{max:10})).join('')}${field('CL1·CL2 약정 주식','settings.psuShares.CL1·CL2',c.psuShares['CL1·CL2'],{unit:'주',step:1})}${field('CL3·CL4 약정 주식','settings.psuShares.CL3·CL4',c.psuShares['CL3·CL4'],{unit:'주',step:1})}${c.psuYears.map((y,i)=>field(`PSU ${i+1}회 지급연도`,`settings.psuYears.${i}`,y,{step:1,min:2020,max:2050})).join('')}</div><hr class="divider"><h3>연간 총소득 합산 세금·사회보험</h3><p class="disclosure">총급여 − 근로소득공제 − 근로자 보험료 = 과세표준. 본인 기본공제 150만원, 부양가족·주택·카드·기부금 및 근로소득세액공제는 기본 제외합니다. 실제 월별 신고·정산과 다른 연간 총액 기반 추정입니다.</p><div class="advanced-grid">${field('지방소득세 / 소득세','settings.tax.local',t.local,{unit:'%',scale:.01,max:100})}${field('2026 국민연금 근로자 부담','settings.tax.pensionStart',t.pensionStart,{unit:'%',scale:.01,max:100})}${field('매년 연금 부담률 상승','settings.tax.pensionStep',t.pensionStep,{unit:'%p',scale:.01,max:10})}${field('국민연금 근로자 요율 상한','settings.tax.pensionMaxRate',t.pensionMaxRate,{unit:'%',scale:.01,max:100})}${field('고용보험 근로자 부담','settings.tax.employment',t.employment,{unit:'%',scale:.01,max:100})}${field('건강보험 근로자 부담','settings.tax.health',t.health,{unit:'%',scale:.01,max:100})}${field('장기요양 / 건강보험료','settings.tax.care',t.care,{unit:'%',scale:.01,max:100})}${field('건강보험 연간 근로자 상한','settings.tax.healthAnnualCap',t.healthAnnualCap,{unit:'만원',scale:10000,hint:'기본 월 4,591,740원 × 12'})}</div><p class="disclosure">2026 연금 연간 상한소득 = 월 637만원 × 6 + 월 659만원 × 6 = 7,776만원. 상한 이상 연봉의 근로자 부담은 369만3,600원. 이후 월 659만원 유지 예시이며 향후 법령 확정값이 아닙니다. 장기요양 13.14%는 0.9448 / 7.19의 반올림값입니다.</p><div class="advanced-grid">${years(state).map(y=>field(`${y} 연금 상한소득`,`settings.tax.pensionCaps.${y}`,t.pensionCaps[y]??79080000,{unit:'만원/년',scale:10000})).join('')}</div><h3 style="margin-top:14px">연간 실제 근로자 국민연금 납입액 (선택)</h3><p class="disclosure">빈칸은 연간 총소득 기반 추정. 직접 입력하면 기본소득과 성과급 합산소득 양쪽에 동일 납입액을 적용하여 성과급에 국민연금 증가분을 부과하지 않습니다. 보험료 소득공제에도 같은 금액을 사용합니다. 2027 건강보험 근로자3.595%를 유지하며 미래 고용보험률은 기본0.9% 가정으로 직접 조정합니다.</p><div class="advanced-grid">${years(state).map(y=>field(y+' 실제 연금 납입액',`settings.tax.pensionPaidByYear.${y}`,t.pensionPaidByYear[y],{unit:'만원/년',scale:10000,placeholder:'자동 추정'})).join('')}</div><details><summary>소득세 8개 누진 구간 수정</summary><div class="table-wrap"><table class="year-form"><thead><tr><th>구간</th><th>과표 상한 (만원)</th><th>세율 (%)</th></tr></thead><tbody>${t.brackets.map(([cap,rate],i)=>`<tr><td>${i+1}</td><td>${cap===null?'상한 없음':`<input type="number" min="1" aria-label="${i+1} 구간 과표상한" data-path="settings.tax.brackets.${i}.0" data-scale="10000" value="${cap/10000}">`}</td><td><input type="number" min="0" max="90" aria-label="${i+1} 구간 소득세율" data-path="settings.tax.brackets.${i}.1" data-scale=".01" value="${rate*100}"></td></tr>`).join('')}</tbody></table></div></details><p class="disclosure">근로소득공제: 500만원 이하 70%, 500–1,500만원 350만원 + 초과 40%, 1,500–4,500만원 750만원 + 초과 15%, 4,500만–1억원 1,200만원 + 초과 5%, 1억원 초과 1,475만원 + 초과 2%, 최대 2,000만원.</p><details><summary>과세 시점 · 원 단위 안분 설명</summary><p class="disclosure">각 개인의 지급연도별로 OPI1·TAI·OPI2·PSU 전액을 먼저 합산합니다. 기본연봉·고정수당 세금/보험료와 합산총소득 세금/보험료의 차이를 성과급 공제로 처리합니다. 이 증분 공제를 지급연도 각 성과급 세전액 비례로 안분하고, 소수 원은 최대잔여법 (잔여가 같은 경우 보상 ID 순)으로 배분합니다. 항목 입력 순서에 독립적이며 원 합계를 보존합니다. OPI2 과세연도는 최초 지급연도, 매각 제한은 세후 가치만 1/3씩 나눕니다.</p><p class="disclosure">종료연도 이후 과세 계산용 연봉은 같은 인상률·상한으로 외삽하며 고정수당도 유지합니다. 연금 상한은 마지막 입력값 유지, 연금 부담률은 설정 상한(기본 2033년 6.5%)까지 상승합니다. 입력 범위 외 신규 성과급은 0이며 미래 연봉은 선택기간 총액·현금흐름에 포함하지 않습니다. 시작연도 이전 발생 성과급은 잔액 입력이 없어 0입니다.</p></details></details>`;}
function renderApp(){const openAdvanced=$('#advanced')?.open;$('#app').innerHTML=`<main class="shell"><div class="topline"><div class="brand"><i class="mark"></i>DS COMPENSATION / PLANNER</div><span class="private">브라우저 로컬 계산 · 입력 전송 없음</span></div><div class="headline"><div><div class="eyebrow">계획의 기준을, 숫자로</div><h1>DS 개인 성과급 계산기</h1><p>보상이 발생한 해와 실제로 현금화할 수 있는 해를 나누어, 개인의 재정계획을 살펴보세요.</p></div></div><div class="notice">공식 사내 계산기가 아닙니다. 공개 보도와 사용자 가정에 기반한 재정계획용 추정 도구입니다. 기존 영업이익 비례 추정 모드의 학술연수·PSU·세후 계산은 사용자 가정입니다. 새 공개안 검토 모드는 선제징수와 최종 연간 세금·정산을 별도 원장으로 다룹니다. 확정 사규·세무 판정이 아닙니다. ${DISCLAIMER}</div>${previousPersonalAvailable?'<div class="notice">이전 개인 조건을 자동 적용하지 않았습니다. 가져오면 새 공개안 정의 확인 상태를 유지합니다. <button data-action="personal-import">이전 개인 조건 가져오기</button></div>':''}${legacyAvailable?'<div class="notice" id="legacy-notice">이전 버전 저장값이 있습니다. 자동으로 적용하지 않았습니다. 첫 번째 개인의 입력만 명시적으로 가져올 수 있으며 이전 저장값은 유지됩니다. <button data-action="legacy-import">이전 저장에서 개인 입력 가져오기</button></div>':''}<div class="toolbar"><div class="actions"><button data-action="save">사용자 조건 저장</button><button data-action="reset">초기화</button></div><div class="actions"><button data-action="json">JSON 내보내기</button><button data-action="import">JSON 불러오기</button><button data-action="csv">CSV 내보내기</button><input type="file" id="import-file" accept=".json,application/json" hidden></div></div><section class="panel" id="inputs"><div class="panel-head"><div><h2>01. 계산 조건</h2><p class="subtitle">원 단위 계산 · 변경 즉시 재계산 · 개인별 연간 총소득 기준 과세</p></div><span class="pill">${state.endYear-state.startYear+1}개년</span></div>${periodEditor()}${policyInputs()}<div class="people" style="grid-template-columns:1fr">${state.people.slice(0,1).map(personEditor).join('')}</div><hr class="divider">${scenarioEditor()}${advanced()}<div class="status-band"><span id="status-text">${esc(status)}</span><span>개인 입력값을 서버로 전송하지 않습니다.</span><span>계약연봉 기준연도: ${state.dataStartYear} · 조회기간을 줄여도 이전 입력분은 보존합니다.</span></div></section><section id="highlights" aria-live="polite"></section><div id="results"></div><section class="panel sources"><h2>참고자료와 가정</h2><p>아래 출처는 이 계산 공식의 공식 인증을 의미하지 않습니다. 특별성과급 보도의 실제 조건과 이 도구의 사용자 지정 단순 비례모델은 다릅니다. 전망값은 사용자 제공 예시이며 최신 정보로 자동 업데이트하지 않습니다.</p><div class="source-list"><a href="https://bonuschip.app/" target="_blank" rel="noopener">보너스칩</a><a href="https://showmethememory.com/" target="_blank" rel="noopener">삼성·하이닉스 성과급 미리보기</a><a href="https://web3.newspim.com/news/view/20260521000075" target="_blank" rel="noopener">삼성전자 DS 특별성과급 공개 보도 · 뉴스핌</a><a href="https://www.khan.co.kr/article/202510141235001/amp" target="_blank" rel="noopener">삼성전자 PSU 공개 보도 · 경향신문</a><a href="https://b.nts.go.kr/nts/cm/cntnts/cntntsView.do?cntntsId=7871&mi=6592" target="_blank" rel="noopener">국세청 · 근로소득공제</a><a href="https://g.nts.go.kr/nts/cm/cntnts/cntntsView.do?cntntsId=7873&mi=6594" target="_blank" rel="noopener">국세청 · 누진 소득세율</a><a href="https://b.nts.go.kr/nts/cm/cntnts/cntntsView.do?cntntsId=239033&mi=40681" target="_blank" rel="noopener">국세청 · 보험료 소득공제</a><a href="https://www.nps.or.kr/pnsinfo/ntpsklg/getOHAF0097M0.do" target="_blank" rel="noopener">국민연금 · 연금개혁</a><a href="https://www.nps.or.kr/pnsgdnc/newgdnc/getOHAE0001M1.do?pstId=ZZ202600000000000147" target="_blank" rel="noopener">국민연금 · 2026 기준소득월액 상한</a><a href="https://edi.nhis.or.kr/portal/images/popup/20251204_pop01longdesc.html" target="_blank" rel="noopener">건강보험 · 2026 요율</a><a href="https://www.nhis.or.kr/lm/lmxsrv/law/lawFullContent.do?SEQ=39&SEQ_HISTORY=595294" target="_blank" rel="noopener">건강보험 · 보험료 상한</a><a href="https://www.moel.go.kr/info/astmgmt/employ/employList.do" target="_blank" rel="noopener">고용노동부 · 고용보험</a></div><p><a href="https://taxlaw.nts.go.kr/qt/USEQTA002P.do?ntstDcmId=010000000000048297" target="_blank" rel="noopener">국세청 · 성과급 귀속시기 사례</a> · <a href="https://law.go.kr/LSW/lsLawLinkInfo.do?chrClsCd=010202&lsJoLnkSeq=900058055" target="_blank" rel="noopener">건강보험 · 전년도 보수 및 정산 근거</a></p><p><a href="https://busan.fnnews.com/news/202605202334386441" target="_blank" rel="noopener">적자 사업부 공통배분 보도</a> · <a href="https://www.newsis.com/view/NISX20260706_0003697549" target="_blank" rel="noopener">TAI 반기 지급 보도</a> · <a href="https://news.nate.com/view/20260623n11755" target="_blank" rel="noopener">학술연수 성과급 보도</a></p><p>보너스칩은 비교 참고용, showmethememory.com은 산식 검증 없이 참고 링크로 제공합니다. 연봉·성과급·PSU 약정, 과세·매각 일정은 실제 사내 안내를 확인해 조정하세요.</p><p>세후 금액은 표준화한 추정치입니다. 부양가족과 연말정산 공제에 따라 실제 금액이 달라질 수 있습니다. 주가는 매각일까지 변하지 않는 평가가치 가정이며 매매 수수료·증권거래세·생활비·부동산 비용은 제외합니다.</p>${warning()}</section><div class="footer"><span>예시 전망 기준 2026.09.05 · 사용자 가정 기반</span><a href="./source.zip" download>계산기 소스 · 테스트 다운로드</a><a href="./README.md" target="_blank">계산·테스트 설명</a><a href="./QA.md" target="_blank">브라우저 검증 기록</a><a href="./validation.csv" download>개인 예시 검증 CSV</a><a href="./validation.json" download>개인 예시 검증 상세 JSON</a></div></main>`;if(openAdvanced)$('#advanced').open=true;renderResults();}
function stat(label,value,cls='',note=''){return `<div class="stat"><div class="label">${label}</div><div class="value ${cls}">${value}</div>${note?`<div class="stat-note">${note}</div>`:''}</div>`;}
function highlight(r){const a=r.accrual[0],n=state.endYear-state.startYear+1,grossCash=a.gross.salary+a.gross.opi1+a.gross.tai,grossStock=a.gross.opi2+a.gross.psu;return `<div class="highlights"><article class="highlight"><div class="period">발생 기준 · 전체 주식 평가가치 포함</div><h2>${state.startYear}년도 총보상은?</h2><div class="hero-label" style="margin-top:16px">세후 총보상 추정</div><div class="hero-number">${amount(a.netTotal)}</div><div class="stats">${stat('세전 총보상',amount(a.grossTotal))}${stat('계약연봉 대비',`${(a.grossTotal/(a.salary||1)).toFixed(2)}배`,'','세전 총보상 ÷ 해당 연도 계약연봉')}${stat('세후 OPI2 전체 가치',a.opi2Pending||a.opi2Incomplete?'미확정 · 부분합계 제외':amount(a.net.opi2),'stock')}${stat('현금성 보상 / 자사주',`${short(a.netCash)} / ${short(a.netStock)}`,'','세후 발생 기준 · 즉시 쓸 수 있는 현금 아님')}</div><div class="mix-track"><div style="width:${a.netTotal?a.netCash/a.netTotal*100:0}%;background:var(--cash)"></div><div style="flex:1;background:var(--stock)"></div></div><div class="legend"><span><i class="dot" style="background:var(--cash)"></i>현금성 발생</span><span><i class="dot" style="background:var(--stock)"></i>자사주 전체 가치</span></div><div class="foot">실제 지급·매도 가능 시점과 관계없이 ${state.startYear}년에 발생한 전체 보상가치를 합산했습니다.</div>${warning()}</article><article class="highlight"><div class="period">${state.startYear}–${state.endYear} · ${n}개년 재정 전망</div><h2>앞으로 ${n}년간 총보상은?</h2><div class="hero-label" style="margin-top:16px">기간 내 현금화 가능액 · 매각 일정 기준 세후 추정</div><div class="hero-number cash">${amount(r.totals.netLiquid)}</div><div class="stats three">${stat('세전 총보상',amount(r.totals.grossAccrual))}${stat('세후 총보상',amount(r.totals.netAccrual))}${stat('연평균 세후 보상',amount(Math.round(r.totals.netAccrual/n)))}${stat(`${state.endYear}년 말 지급된 매도제한 잔액`,amount(r.locked.paidLockedStock),'locked')}${stat('아직 지급되지 않은 주식가치',amount(r.locked.unpaidStock),'stock')}${stat('계약연봉 대비',`${(r.totals.grossAccrual/(r.totals.contract||1)).toFixed(2)}배`,'','세전 총보상 ÷ 같은 기간 계약연봉 합계')}</div><div class="foot">선택한 주식 매각 일정과 현금 정산연도를 포함한 추정입니다. 실제 보험료 결정/정산 시차는 미반영합니다. ${state.endYear}년 발생 OPI1도 발생 총액에 포함하며 기본 다음 해 지급으로 기간 내 현금에서 제외합니다. 미지급 현금성 보상 및 정산 순잔액 ${amount(r.locked.unpaidCash)}. 미현금화 주식 총계 ${amount(r.locked.totalStock)}. ${r.opening.total?`기초 보상 잔액 ${amount(r.opening.total)}도 선택기간의 현금유입에 포함합니다.`:''}</div>${warning()}</article></div>`;}
function tipHTML(title,parts,total){return `<strong>${esc(title)}</strong>${TYPES.map(k=>`<div class="tip-row"><span style="color:${COLORS[k]}">${LABELS[k]}</span><span>${amount(parts[k]||0)}</span></div>`).join('')}<hr class="divider"><div class="tip-row"><strong>합계</strong><strong>${amount(total)}</strong></div><div class="tiny muted">${DISCLAIMER}</div>`;}
function bars(rows,key='net',totalKey='netTotal',title=''){const max=Math.max(1,...rows.map(r=>r[totalKey]));return `<div class="plot"><span class="axis">${short(max)}</span>${rows.map(r=>`<div class="bar-group" tabindex="0" data-tip="${esc(tipHTML(String(r.year)+' · '+title,r[key],r[totalKey]))}"><span class="bar-number">${short(r[totalKey])}</span><div class="bar" style="height:${Math.max(.2,r[totalKey]/max*88)}%">${TYPES.map(k=>`<div class="bar-segment" style="height:${r[totalKey]?Math.max(0,r[key][k]??0)/sum(Object.values(r[key]).filter(v=>v>0))*100:0}%;background:${COLORS[k]}"></div>`).join('')}</div><span class="bar-year">${r.year}</span></div>`).join('')}</div><div class="chart-foot">마우스 또는 키보드 포커스로 종류별 세부금액 확인 · 단위 억원</div>`;}
const legend=()=>`<div class="legend">${TYPES.map(k=>`<span><i class="dot" style="background:${COLORS[k]}"></i>${LABELS[k]}</span>`).join('')}</div>`;
function cumulativeChart(r){let cash=0,stock=0;const parts=Object.fromEntries(TYPES.map(k=>[k,0]));const rows=r.accrual.map(a=>{cash+=a.netCash;stock+=a.netStock;TYPES.forEach(k=>parts[k]+=a.net[k]);return {...a,parts:{...parts},net:{salary:cash,opi1:0,tai:0,opi2:stock,psu:0},netTotal:cash+stock};});const max=Math.max(1,...rows.map(a=>a.netTotal)),points=rows.map((a,i)=>({x:40+i*480/Math.max(1,rows.length-1),cashY:190-a.net.salary/max*160,totalY:190-a.netTotal/max*160}));return `<svg viewBox="0 0 560 225" role="img" aria-label="발생 기준 세후 현금성 보상과 자사주 누적 구성"><path d="M40,190 ${points.map(p=>`L${p.x},${p.cashY}`).join(' ')} L520,190Z" fill="#57d9ba44"/><path d="${points.map((p,i)=>`${i?'L':'M'}${p.x},${p.totalY}`).join(' ')} ${[...points].reverse().map(p=>`L${p.x},${p.cashY}`).join(' ')}Z" fill="#98a8ff55"/><polyline points="${points.map(p=>`${p.x},${p.totalY}`).join(' ')}" fill="none" stroke="#98a8ff" stroke-width="3"/><polyline points="${points.map(p=>`${p.x},${p.cashY}`).join(' ')}" fill="none" stroke="#57d9ba" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.totalY}" r="6" fill="#98a8ff" tabindex="0" data-tip="${esc(tipHTML(rows[i].year+' 누적 발생',rows[i].parts,rows[i].netTotal))}"/><text x="${p.x}" y="218" text-anchor="middle" fill="#96abc2" font-size="12">${rows[i].year}</text>`).join('')}<text x="5" y="22" fill="#96abc2" font-size="11">${short(max)}</text></svg><div class="legend"><span class="cash">● 현금성 보상 누적 발생액</span><span class="stock">● 자사주 전체 누적 발생가치</span></div><p class="disclosure">매각 여부와 무관한 발생 기준 구성입니다. 실제 현금화 누적은 현금흐름 표를 확인하세요.</p>`;}
function comparisonBars(items){const max=Math.max(1,...items.map(i=>i.value));return `<div class="plot">${items.map(i=>`<div class="bar-group" tabindex="0" data-tip="${esc(i.tip)}"><span class="bar-number">${short(i.value)}</span><div class="bar" style="height:${i.value/max*88}%;background:${i.color}"></div><span class="bar-year">${esc(i.label)}</span></div>`).join('')}</div><div class="chart-foot">기간 내 세후 현금화 가능액 비교 · 생활비·주택비 차감 전</div>`;}
function resultsTable(r){const net=state.display.tax==='net',basis=state.display.basis,rows=r[basis],key=net?'net':'gross';const head=basis==='accrual'?['연도','계약연봉','고정수당','OPI1','TAI','OPI2 세전 총가치','OPI2 세후 총가치','PSU','세전 총보상','세후 총보상','현금성 발생','자사주 발생','🔒 연말 미현금화 주식']:['연도',net?'세후 연봉·수당':'세전 연봉·수당','수령 OPI1','수령 TAI','매각 가능 OPI2','매각 가능 PSU','세금·보험 현금 정산','연간 현금화 가능 합계','누적 현금화 가능액'];let cumulative=0;const body=rows.map(a=>{cumulative+=a[key+'Total'];const values=basis==='accrual'?[amount(a.salary),amount(a.allowance),amount(a[key].opi1),amount(a[key].tai),a.opi2Pending?'미확정 · 제외':amount(a.gross.opi2),a.opi2Pending||a.opi2Incomplete?'미확정 · 제외':amount(a.net.opi2),amount(a[key].psu),amount(a.grossTotal),amount(a.netTotal),amount(net?a.netCash:a[key].salary+a[key].opi1+a[key].tai),amount(net?a.netStock:a[key].opi2+a[key].psu),amount(net?a.lockedStock:sum(a.details.filter(e=>['opi2','psu'].includes(e.type)).flatMap(e=>e.tranches.filter(t=>t.year>a.year)).map(t=>t.gross)))]:[amount(a[key].salary),amount(a[key].opi1),amount(a[key].tai),amount(a[key].opi2),amount(a[key].psu),amount(a[key].settlement??0),amount(a[key+'Total']),amount(cumulative)];return `<tr><td><strong>${a.year}</strong>${basis==='accrual'?a.reasons.filter(x=>x!=='지급 기준 충족').map(x=>`<div class="reason">${esc(x)}</div>`).join(''):''}</td>${values.map((v,i)=>`<td class="${basis==='cashflow'&&i===3?'stock':basis==='accrual'&&i===11?'locked':''}">${v}</td>`).join('')}</tr>`;}).join('');return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div><p class="disclosure">${basis==='accrual'?'계약연봉·수당 열은 입력 세전액이며 OPI2 두 열과 총액 두 열은 각각의 세전/세후값을 고정 표시합니다. 나머지 보상 열은 선택한 세전/세후 기준입니다. 현금성 발생액은 실제 지급 현금과 다릅니다. 연말 미현금화 주식에는 미지급과 지급된 매도제한이 함께 포함됩니다.':'새모드 OPI2 매각액은 선징수 후 주식예산을 지급일 종가로 평가해 3회 분할한 값입니다. 최종 세금 차이는 정산 현금 열에 별도로 반영됩니다. 입력 기준연도 이전 미입력 잔액은 0이며 이전에 입력한 보상 회차는 보존합니다.'}</p>`;}
function roundsTable(r){const es=r.people.flatMap(p=>p.events.filter(e=>e.type==='opi2').map(e=>({...e,name:p.person.name})));return `<div class="table-wrap"><table><thead><tr>${['성과 발생연도','세전 총액','세후 총액','과세 / 최초 지급','1차 매각','2차 매각','3차 매각',`${state.endYear}년 이후 미현금화 잔액`].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${es.map(e=>`<tr><td>${e.origin}${e.reason?`<div class="reason">${esc(e.reason)}</div>`:''}</td><td>${amount(e.gross)}</td><td>${e.net===null?'미완료 · 추가납부 필요':amount(e.net)}</td><td>${e.payYear}년</td>${e.tranches.map(t=>`<td class="${t.year>state.endYear?'locked':'stock'}">${t.year}년 / ${amount(t.net)} ${t.year>state.endYear?'🔒':''}</td>`).join('')}<td class="locked">${amount(sum(e.tranches.filter(t=>t.year>state.endYear).map(t=>t.net)))}</td></tr>`).join('')}</tbody></table></div><p class="disclosure">종료연도 이후 회차도 잔액 추적을 위해 표시하며 선택기간 총 현금흐름에서는 제외합니다. 지급연도 신고소득으로 최종 누진 부담을 추정하고 선징수 차이는 별도 현금 정산합니다. 새모드 세후 총액은 주식 종가평가+정산이며 세 매각 회차에는 주식평가액만 분할합니다.</p>`;}
function scenarioResults(scenarios){return `<div class="metrics-grid">${Object.entries(scenarios).map(([k,r])=>`<article class="mini-card"><div class="inline"><h3>${esc(r.scenario.name)}</h3>${state.activeScenario===k?'<span class="badge">현재 적용</span>':''}</div><div class="big">${amount(r.totals.netLiquid)}</div><div class="tiny muted">세후 발생 ${amount(r.totals.netAccrual)}<br>미현금화 주식 ${amount(r.locked.totalStock)}</div><button style="margin-top:10px" data-action="scenario" data-scenario="${k}">이 시나리오 적용</button>${warning()}</article>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>연도</th>${Object.values(scenarios).map(r=>`<th>${esc(r.scenario.name)} 현금화</th>`).join('')}</tr></thead><tbody>${years(state).map((y,i)=>`<tr><td>${y}</td>${Object.values(scenarios).map(r=>`<td>${amount(r.cashflow[i].netTotal)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="disclosure">저장 시나리오 3개(중간·하락·사용자 지정)를 동시에 비교합니다. 기본·보수·낙관은 현재 시나리오 입력값을 채우는 별도 프리셋입니다.</p>${warning()}`;}
function validationUI(){const warnings=reports.reduce((s,r)=>s+r.checks.filter(c=>c.warning).length,0);return `<section class="panel"><div class="panel-head"><div><h2>검증값과 계산 차이</h2><p class="subtitle">일반 개인 예시 · 현재 세율/보험료 설정 · 3개 지정 시나리오 자동 계산</p></div><span class="pill difference">${warnings}개 항목에 1% 초과 차이</span></div><p class="disclosure">아래는 이전 순세후 모형의 회귀 검사이며 새모드의 선징수·기부·정산 결과에 맞추는 정답이 아닙니다. 현재 입력값과 별도로 일반 개인 예시·현재 고급 설정을 이용한 재현 검사입니다. 검증값에 맞춰 금액을 고정하지 않습니다. 현재 조건의 지급연도별 세금 로그는 상세 결과에서 확인할 수 있습니다.</p><div class="notice">계산 방식 진단: 이 도구는 지급연도에 OPI1·TAI·OPI2·PSU를 함께 과세하고, 보험료 소득공제를 적용하며, 증분 세금·보험료를 세전 비중대로 안분합니다. 일반 개인 예시(기준연봉 8,500만원·고정수당 0원·연수 없음)의 고정 회귀 기준과 비교합니다. 설정을 바꾸면 기준값과 달라질 수 있습니다.</div>${reports.map(rep=>`<details><summary>${rep.name} · 계산 누적 ${amount(rep.result.totals.netLiquid)}</summary><div class="table-wrap"><table><thead><tr><th>연도 / 개인 / 항목</th><th>기본 회귀 기준</th><th>현재 산식</th><th>차이</th><th>차이율</th></tr></thead><tbody>${rep.checks.map(c=>`<tr><td>${esc(c.label)}</td><td>${amount(c.expected)}</td><td>${amount(c.actual)}</td><td class="${c.warning?'difference':''}">${amount(c.difference)}</td><td>${(c.percent*100).toFixed(2)}% ${c.warning?'△':''}</td></tr>`).join('')}</tbody></table></div><div class="actions" style="margin-top:10px"><button data-action="validation-log" data-key="${rep.key}">연도·개인·항목별 진단 JSON</button></div><details><summary>현재 설정의 지급연도 과세 로그</summary><pre class="log">${esc(JSON.stringify(rep.result.people.map(p=>({name:p.person.name,taxLog:p.taxLog})),null,2))}</pre></details>${warning()}</details>`).join('')}<div class="actions" style="margin-top:14px"><button data-action="validation-csv">3개 시나리오 검증 CSV</button></div>${warning()}</section>`;}
function renderResults(){window.__planner={input:()=>JSON.parse(JSON.stringify(state)),result:()=>calculate(state),export:()=>reviewExport(),reports:()=>reports,resultModel:()=>state.opi2Policy.mode};let r,sc;try{validateState(state);r=calculate(state);sc=compare(state);reports=validationReport(state.settings);}catch(e){$('#highlights').innerHTML=`<div class="error">${esc(e.message)}</div>`;$('#results').innerHTML='';return;}$('#highlights').innerHTML=(state.opi2Policy.mode==='review'?integratedNotice(r):'<div class="notice">기존 영업이익 비례 추정 모드입니다. 새 공개안과 분리된 참고 결과입니다.</div>')+highlight(r);r.people.forEach((p,i)=>{const el=$('#psu-total-'+i);if(el)el.textContent='최종 PSU '+p.psuShares.toLocaleString()+'주 · 지급연도별 계산상 평가수량 '+(p.psuShares/3).toLocaleString('ko-KR',{maximumFractionDigits:4})+'주. '+state.settings.psuYears.join('·')+'년 전체 평가가치를 1/3씩 지급. 소수 주식은 계산상 평가수량, 실제 지급 단위 미확인. 학술연수에도 별도 선택 유지.';});for(const y of years(state)){const s=state.scenarios[state.activeScenario],reason=s.unpaid[y]||s.opi2Factor===0?'사용자 미지급 가정':state.opi2Policy.mode==='review'&&state.opi2Policy.rateSource==='direct'?'직접 지급률 가정':(s.performance[y]??0)<(state.settings.thresholds[y]??(y<=2028?200:100))?'지급 기준 미달':'지급 기준 충족';const el=$(`#eligibility-${y}`);if(el)el.innerHTML=`<span class="${reason==='지급 기준 충족'?'cash':'difference'}">${reason}</span>`;state.people.forEach((p,i)=>{const e=$(`#salary-${i}-${y}`);if(e)e.textContent=amount(salaryAt(p,y,state));});}const view=r,key=state.display.tax,totalKey=key+'Total';const opt=JSON.parse(JSON.stringify(state.scenarios.middle));opt.name='낙관적 예시';opt.performance=Object.fromEntries(years(state).map(y=>[y,(defaults().scenarios.middle.performance[y]??state.scenarios.middle.performance[y]??0)*1.25]));opt.unpaid={};const optimistic=calculate(state,opt);const presetRows=[['기본 예시',calculate(state,defaults().scenarios.middle),'#57d9ba'],['보수 예시',calculate(state,defaults().scenarios.downturn),'#d9b77c'],['낙관 ×1.25',optimistic,'#98a8ff']];$('#results').innerHTML=`<div class="toolbar"><div class="segments"><span class="muted tiny">표·첫 두 그래프</span><button data-action="tax" data-value="net" class="${key==='net'?'active':''}">세후</button><button data-action="tax" data-value="gross" class="${key==='gross'?'active':''}">세전</button><button data-action="basis" data-value="accrual" class="${state.display.basis==='accrual'?'active':''}">발생 기준</button><button data-action="basis" data-value="cashflow" class="${state.display.basis==='cashflow'?'active':''}">현금화 기준</button></div><button data-action="copy" class="secondary">재정설계용 요약 복사</button></div><div class="summary-box" id="summary-box"><label for="summary-text">복사 권한이 없을 때 아래 내용을 직접 복사하세요</label><textarea id="summary-text" readonly></textarea></div><section class="panel"><div class="panel-head"><div><h2>02. 보상과 유동성의 흐름</h2><p class="subtitle">두 기준을 함께 확인하세요 · 하이라이트 카드는 항상 세전·세후 구분 표시</p></div><span class="pill">${key==='net'?'세후 추정':'세전 평가'}</span></div><div class="charts"><div class="chart"><h3>연도별 ${key==='net'?'세후':'세전'} 총보상 · 발생</h3>${bars(r.accrual,key,totalKey,'발생')}${legend()}${warning()}</div><div class="chart"><h3>연도별 현금화 가능액 · ${key==='net'?'세후':'세전'}</h3>${bars(r.cashflow,key,totalKey,'현금화')}${legend()}${warning()}</div><div class="chart"><h3>현금성 보상 · 자사주 누적 구성 · 세후</h3>${cumulativeChart(r)}${warning()}</div><div class="chart"><h3>기본 · 보수 · 낙관 입력 프리셋 비교</h3>${comparisonBars(presetRows.map(([label,result,color])=>({label,value:result.totals.netLiquid,color,tip:tipHTML(label+' · 세후 현금화',Object.fromEntries(TYPES.map(k=>[k,sum(result.cashflow.map(c=>c.net[k]))])),result.totals.netLiquid)})))}<p class="disclosure">같은 개인 조건에 입력 프리셋만 적용. 낙관은 ×1.25 사용자 조정 예시입니다. 아래 저장 시나리오와 별도입니다.</p>${warning()}</div></div></section><section class="panel"><div class="panel-head"><div><h2>03. 상세 보상표</h2><p class="subtitle">${state.startYear}–${state.endYear} · 연도별 추적 가능</p></div><span class="pill">개인 상세 결과</span></div><div class="tabs">${[['accrual','A. 발생 기준'],['cashflow','B. 실제 현금화'],['rounds','C. OPI2 회차'],['taxlog','지급연도 과세 로그']].map(([k,v])=>`<button class="tab ${tab===k?'active':''}" data-action="tab" data-value="${k}">${v}</button>`).join('')}</div><div class="mobile-hint">표를 좌우로 스크롤해 모든 항목을 확인하세요.</div>${tab==='rounds'?roundsTable(r):tab==='taxlog'?`<p class="disclosure">지급연도 전액 합산 과세 · 기본세금과의 차이 · 보상별 안분 공제. 미래 연봉은 세금 추정에만 사용합니다.</p><pre class="log">${esc(JSON.stringify(r.people.map(p=>({name:p.person.name,taxLog:p.taxLog})),null,2))}</pre>`:resultsTable(view)}${warning()}<details><summary>현금화 내역의 OPI2 발생연도 추적</summary><div class="table-wrap"><table><thead><tr><th>현금화연도</th><th>발생연도</th><th>최초 지급·과세연도</th><th>항목</th><th>세후 매각가치</th></tr></thead><tbody>${view.cashflow.flatMap(c=>c.details.filter(t=>t.type==='opi2').map(t=>`<tr><td>${c.year}</td><td>${t.origin}</td><td>${t.payYear}</td><td>OPI2</td><td>${amount(t.net)}</td></tr>`)).join('')}</tbody></table></div>${warning()}</details></section><section class="panel"><div class="panel-head"><div><h2>04. 저장 시나리오 3개 동시 비교</h2><p class="subtitle">중간 전망 · 반도체 하락 전망 · 사용자 지정</p></div></div>${scenarioResults(sc)}</section>${state.opi2Policy.mode==='review'?integratedDetails(r):''}${validationUI()}<section class="panel"><h3>${state.endYear}년 이후 미현금화 잔액</h3><div class="grid three" style="margin-top:14px">${stat('이미 지급된 매도제한 주식',amount(r.locked.paidLockedStock),'locked')}${stat('발생했으나 아직 미지급인 주식',amount(r.locked.unpaidStock),'stock')}${stat('미지급 현금 보상·정산 순채권',amount(r.locked.unpaidCash),'cash')}</div><p class="disclosure">선택기간 발생 보상과 이전 입력분의 기초 보상 잔액을 추적합니다. 선택기간 이후에 새로 발생하는 보상은 총액에 포함하지 않습니다. 주가 변동·수수료·증권거래세·생활비·부동산 비용을 차감하지 않은 총유입액입니다. 매각세금·매매수수료는 0원 가정입니다.</p><p class="disclosure">원 단위 장부: 기초 보상잔액 ${r.opening.total.toLocaleString()}원 + 선택기간 세후 발생 ${r.totals.netAccrual.toLocaleString()}원 = 선택기간 세후 현금화 ${r.totals.netLiquid.toLocaleString()}원 + 종료시점 미현금화(주식·현금) ${(r.locked.totalStock+r.locked.unpaidCash).toLocaleString()}원.</p>${warning()}</section>`;window.__planner={input:()=>JSON.parse(JSON.stringify(state)),result:()=>calculate(state),export:()=>reviewExport(),reports:()=>reports};}
function pathSet(path,value){const keys=path.split('.');if(keys.some(k=>['__proto__','constructor','prototype'].includes(k)))throw Error('잘못된 입력 경로');let o=state;for(const k of keys.slice(0,-1))o=o[k]??(o[k]={});const last=keys.at(-1);if(value===undefined)delete o[last];else o[last]=value;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function download(name,text,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff',text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
function csvExport(){const r=calculate(state),rows=[['모델',r.resultModel??'legacy_reference','확정값 아님',r.disclaimer??DISCLAIMER],['구분','연도',...TYPES.map(k=>LABELS[k]+' 세전 원'),...TYPES.map(k=>LABELS[k]+' 세후 원'),'세전합계 원','세후합계 원','세후누적 원','비고']];for(const basis of ['accrual','cashflow'])for(const a of r[basis])rows.push([basis==='accrual'?'발생':'현금화',a.year,...TYPES.map(k=>a.gross[k]),...TYPES.map(k=>a.net[k]),a.grossTotal,a.netTotal,a.cumulative??'',a.opi2Pending||a.opi2Incomplete?'OPI2 미확정/미완료 제외한 부분합계 · 0원 확정 아님':DISCLAIMER]);rows.push(['잔액',state.endYear,'미지급 주식',r.locked.unpaidStock,'지급된 매도제한 주식',r.locked.paidLockedStock,'미지급 현금성 보상',r.locked.normalUnpaidCash??r.locked.unpaidCash,'기간 이후 정산채권',r.locked.settlementReceivable??0,'기간 이후 정산채무',r.locked.settlementPayable??0]);if(r.settlementEvents){rows.push(['정산 종류','발생연도','과세연도','현금 정산연도','원','가정']);for(const e of r.settlementEvents)rows.push([e.kind,e.origin,e.payYear,e.year,e.net,'선택연도 현금 정산 추정 · 주식수 변경 없음']);rows.push(['OPI2 발생연도','세전G','근로소득Y','원가기준 주식예산','종가 주식가치','시장평가 조정','선제 세금','선제 보험','기부','최종 세금 추정','최종 보험 추정']);for(const e of r.events.filter(e=>e.type==='opi2'))rows.push([e.origin,e.gross,e.taxableIncome,e.snapshot.benchmarkStockBudget,e.snapshot.estimatedStockMarketValue??'미완료',e.marketAdjustment??'미완료',e.snapshot.withheldTax,e.snapshot.withheldInsurance,e.snapshot.donation,e.finalTaxEstimate,e.finalInsuranceEstimate]);}rows.push(['저장 시나리오','연도','현금화 원','누적 원']);for(const [key,v]of Object.entries(compare(state)))for(const c of v.cashflow)rows.push([key,c.year,c.netTotal,c.cumulative]);return rows.map(row=>row.map(csvCell).join(',')).join('\r\n');}

function summary(){const d=exportData(state),r=calculate(state);return [`DS 개인 재정설계용 요약 | ${state.startYear}–${state.endYear}`,DISCLAIMER,'매각 및 선택한 현금 정산 기준의 추정이며 실제 보험료 결정·정산 시차는 미반영. 생활비와 부동산 비용이 차감되지 않은 총유입액. 주가가 매각일까지 일정한 평가가치 가정; 수수료·증권거래세 제외.','범위 이전 발생 보상은 입력이 없어 0. OPI2 전액 최초 지급연도 과세; 같은 해 증분공제를 세전액 비례 안분.',...r.people.flatMap(p=>[`${p.person.name} (${p.person.division})`,...p.accrual.map((a,i)=>{const c=p.cashflow[i];return `${a.year}: 계약연봉 ${amount(a.salary)}; 세후연봉·수당 ${amount(c.net.salary)}; 수령 OPI1 ${amount(c.net.opi1)} / TAI ${amount(c.net.tai)}; OPI2 발생 세전 ${amount(a.gross.opi2)}·세후 ${amount(a.net.opi2)} / 매각 ${amount(c.net.opi2)}; PSU 지급가치 ${amount(a.net.psu)} / 매각 ${amount(c.net.psu)}; 세금·보험 정산 현금 ${amount(c.net.settlement??0)}; 총 현금화 ${amount(c.netTotal)}; 누적 ${amount(c.cumulative)}`;}),`개인 ${state.endYear} 이후 주식잔액 ${amount(p.locked.totalStock)} (미지급 ${amount(p.locked.unpaidStock)}, 지급된 매도제한 ${amount(p.locked.paidLockedStock)})`]),'연도별 현금화: '+r.cashflow.map(c=>`${c.year} ${amount(c.netTotal)} (누적 ${amount(c.cumulative)})`).join(' / '),'총 현금화 '+amount(r.totals.netLiquid),'기간 이후 정산채권 '+amount(r.locked.settlementReceivable??0)+' / 정산채무 '+amount(r.locked.settlementPayable??0),'영업이익 가정 (조원): '+JSON.stringify(d.performanceScenario),'선징수/정산 가정: '+JSON.stringify(state.opi2Policy),'세율·보험료: '+JSON.stringify(state.settings.tax),'저장 시나리오: '+Object.values(d.scenarioComparison).map(s=>`${s.name} ${amount(s.totals.netLiquid)}`).join(' / '),'입력 프리셋 비교: '+Object.entries(d.inputPresetComparison).map(([k,v])=>k+' '+amount(v.totals.netLiquid)).join(' / ')+' (낙관은 사용자 조정 예시 ×1.25).',d.disclaimer,JSON.stringify(d,null,2)].join('\n');}
function applyPreset(type,year){const base=defaults().scenarios.middle.performance,sc=state.scenarios[state.activeScenario];for(const y of year?[year]:years(state)){if(type==='conservative'){if([2028,2029].includes(y))sc.unpaid[y]=true;else if([2026,2027].includes(y)){sc.performance[y]=base[y];sc.unpaid[y]=false;}}else{sc.performance[y]=(base[y]??sc.performance[y]??0)*(type==='optimistic'?1.25:1);sc.unpaid[y]=false;}}}
document.addEventListener('input',e=>{const el=e.target;if(!el.dataset.path||el.type==='checkbox'||el.tagName==='SELECT')return;const path=el.dataset.path;if(el.type==='number'&&el.value!==''&&!el.validity.valid){el.setAttribute('aria-invalid','true');$('#status-text').textContent='입력 범위를 확인하세요. 잘못된 입력은 적용하지 않았으며 결과는 직전 유효 입력 기준입니다.';return;}el.removeAttribute('aria-invalid');$('#status-text').textContent=status;const v=el.type==='date'?(el.value||undefined):el.type==='number'?(el.value===''?undefined:(Number(el.dataset.scale||1)>=1?Math.round(Number(el.value)*Number(el.dataset.scale||1)):Number((Number(el.value)*Number(el.dataset.scale||1)).toFixed(8)))):el.value;const previousDefaultGrowth=state.settings.growth;pathSet(path,v);if(path==='settings.growth'&&v!==undefined){state.people.forEach((p,i)=>{if(p.growth===previousDefaultGrowth){p.growth=v;const input=document.querySelector('[data-path="people.'+i+'.growth"]');if(input)input.value=Number((v*100).toFixed(6));}});}if(path==='startYear'||path==='endYear'){const start=state.startYear,end=state.endYear;if(start<state.dataStartYear)state.dataStartYear=start;if(start>=2020&&end>=start&&end-start<15&&end<=2050)renderApp();else renderResults();}else renderResults();});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='import-file'){try{if(!el.files[0])return;if(el.files[0].size>2000000)throw Error('JSON 파일은 2MB 이하로 선택하세요.');const imported=importConditions(await el.files[0].text());state=imported.state;status=imported.notice;renderApp();toast(status);}catch(err){toast(err.message);}return;}if(el.dataset.yearPreset){applyPreset(el.value,Number(el.dataset.yearPreset));renderApp();return;}if(!el.dataset.path)return;if(el.type==='checkbox')pathSet(el.dataset.path,el.checked);else if(el.tagName==='SELECT'){const value=['settings.opi2Delay','people.0.psuMultiplier'].includes(el.dataset.path)||el.dataset.path.endsWith('opi2Factor')||el.dataset.path==='opi2Policy.donationRate'?Number(el.value):(el.value===''?undefined:el.value);pathSet(el.dataset.path,value);}else return;if(el.dataset.path==='settings.opi2Delay'){for(const y of years(state))if(!state.opi2Policy.paymentDateConfirmedByYear[y]){state.opi2Policy.paymentDateByYear[y]=(y+Number(el.value))+'-04-01';state.opi2Policy.expectedPaymentYearByYear[y]=y+Number(el.value);}}if(el.dataset.path==='opi2Policy.mode'||el.dataset.path==='display.format'||el.dataset.path==='settings.opi2Delay'||el.dataset.path.endsWith('.grade'))renderApp();else renderResults();});
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(!btn)return;try{switch(btn.dataset.action){case 'personal-import':{const raw=localStorage.getItem(PREVIOUS_PERSONAL_KEY);if(!raw)throw Error('이전 개인 저장값이 없습니다.');const imported=importConditions(raw);state=imported.state;state.opi2Policy.mode='review';status='이전 개인 조건만 가져왔습니다. 새 공개안 정의는 확인 대기이며 원본 저장값은 변경하지 않았습니다.';renderApp();toast(status);break;}case 'legacy-import':{const raw=localStorage.getItem(LEGACY_KEY);if(!raw)throw Error('이전 저장값이 없습니다.');const imported=importConditions(raw);state=imported.state;status=imported.notice;renderApp();toast(status);break;}case 'reset':state=defaults();localStorage.removeItem(KEY);status='공개안 입력 검토 기본값으로 초기화했습니다. 새 검토본 저장값만 삭제하며 이전 개인·구형 저장값은 유지합니다.';renderApp();toast(status);break;case 'save':validateState(state);localStorage.setItem(KEY,JSON.stringify(state));status='개인 조건과 3개 시나리오·선징수/정산 가정을 새 v3 저장소에 보관했습니다. 이전 저장값은 유지합니다.';$('#status-text').textContent=status;toast(status);break;case 'json':download('DS-개인-재정계획-'+state.startYear+'-'+state.endYear+'.json',JSON.stringify(reviewExport(),null,2));toast('JSON 내보내기 완료');break;case 'import':$('#import-file').value='';$('#import-file').click();break;case 'csv':download('DS-개인-보상-현금흐름.csv',csvExport(),'text/csv;charset=utf-8');toast('CSV 내보내기 완료');break;case 'copy':{const text=summary();try{await navigator.clipboard.writeText(text);toast('재정설계용 요약을 복사했습니다.');}catch{$('#summary-box').classList.add('visible');$('#summary-text').value=text;$('#summary-text').focus();$('#summary-text').select();toast('복사 권한이 없어 선택된 요약을 직접 복사하세요.');}break;}case 'growth':state.people[btn.dataset.person].growth=state.settings.growth;renderApp();break;case 'scenario':state.activeScenario=btn.dataset.scenario;renderApp();break;case 'save-scenario':state.scenarios.custom=JSON.parse(JSON.stringify(state.scenarios[state.activeScenario]));state.scenarios.custom.name='사용자 지정';state.activeScenario='custom';renderApp();toast('현재 전망과 토글을 사용자 지정 시나리오에 저장했습니다.');break;case 'performance-preset':applyPreset(btn.dataset.preset);renderApp();break;case 'tax':state.display.tax=btn.dataset.value;renderResults();break;case 'basis':state.display.basis=btn.dataset.value;tab=state.display.basis;renderResults();break;case 'tab':tab=btn.dataset.value;if(['accrual','cashflow'].includes(tab))state.display.basis=tab;renderResults();break;case 'validation-log':download('DS-검증-'+btn.dataset.key+'.json',JSON.stringify(reports.find(r=>r.key===btn.dataset.key),null,2));break;case 'validation-csv':download('DS-3개시나리오-검증.csv',[['시나리오','항목','기본 기준 원','계산값 원','차이 원','차이율'],...reports.flatMap(r=>r.checks.map(c=>[r.name,c.label,c.expected,c.actual,c.difference,c.percent]))].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');break;}}catch(err){toast(err.message);}});
function showTip(target,x,y){const tip=$('#tooltip');tip.innerHTML=target.dataset.tip;tip.style.display='block';tip.style.left=Math.max(8,Math.min(x+14,window.innerWidth-tip.offsetWidth-10))+'px';tip.style.top=Math.max(8,Math.min(y+14,window.innerHeight-tip.offsetHeight-10))+'px';}
document.addEventListener('pointerover',e=>{const t=e.target.closest('[data-tip]');if(t)showTip(t,e.clientX,e.clientY);});document.addEventListener('pointermove',e=>{const t=e.target.closest('[data-tip]');if(t)showTip(t,e.clientX,e.clientY);});document.addEventListener('pointerout',e=>{if(e.target.closest('[data-tip]'))$('#tooltip').style.display='none';});document.addEventListener('focusin',e=>{if(e.target.dataset.tip){const b=e.target.getBoundingClientRect();showTip(e.target,b.left,b.top);}});document.addEventListener('focusout',()=>$('#tooltip').style.display='none');
renderApp();
